begin read only;
set local search_path=pg_catalog,public;
select jsonb_build_object(
'policy_column',(select jsonb_agg(t) from (select column_name,data_type,is_nullable,column_default from information_schema.columns where table_schema='public' and table_name='essay_practice_sessions' and column_name='billing_policy_version') t),
'new_execute',(select jsonb_agg(t) from (select n.nspname,p.proname,role,has_function_privilege(role,p.oid,'EXECUTE') executable from pg_proc p join pg_namespace n on n.oid=p.pronamespace cross join unnest(array['anon','authenticated','service_role','essay_worker','essay_finance','essay_executor']) role where (n.nspname='essay_private' and p.proname like 'credit_%') or (n.nspname='public' and p.proname in ('essay_admin_grant','essay_claim_signup_credit')) order by 1,2,3) t),
'profile_trigger',(select jsonb_agg(pg_get_triggerdef(t.oid) order by t.tgname) from pg_trigger t where t.tgrelid='public.profiles'::regclass and t.tgname='essay_signup_credit'),
'executor_grant_insert',has_table_privilege('essay_executor','public.credit_grants','INSERT'),
'activation',(select jsonb_agg(jsonb_build_object('source',p.prosrc,'owner',pg_get_userbyid(p.proowner),'path',p.proconfig,'definer',p.prosecdef)) from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='essay_private' and p.proname='credit_signup_eligible'),
'product_fingerprints',(select jsonb_object_agg(name,fingerprint) from (
select 'essay_questions' name,md5(coalesce(string_agg((to_jsonb(t)-'billing_policy_version')::text,'' order by (to_jsonb(t)-'billing_policy_version')::text),'')) fingerprint from public.essay_questions t union all select 'essay_question_evidence' name,md5(coalesce(string_agg((to_jsonb(t)-'billing_policy_version')::text,'' order by (to_jsonb(t)-'billing_policy_version')::text),'')) fingerprint from public.essay_question_evidence t union all select 'essay_evaluation_criteria' name,md5(coalesce(string_agg((to_jsonb(t)-'billing_policy_version')::text,'' order by (to_jsonb(t)-'billing_policy_version')::text),'')) fingerprint from public.essay_evaluation_criteria t union all select 'student_target_universities' name,md5(coalesce(string_agg((to_jsonb(t)-'billing_policy_version')::text,'' order by (to_jsonb(t)-'billing_policy_version')::text),'')) fingerprint from public.student_target_universities t union all select 'essay_practice_sessions' name,md5(coalesce(string_agg((to_jsonb(t)-'billing_policy_version')::text,'' order by (to_jsonb(t)-'billing_policy_version')::text),'')) fingerprint from public.essay_practice_sessions t union all select 'essay_drafts' name,md5(coalesce(string_agg((to_jsonb(t)-'billing_policy_version')::text,'' order by (to_jsonb(t)-'billing_policy_version')::text),'')) fingerprint from public.essay_drafts t union all select 'essay_attempts' name,md5(coalesce(string_agg((to_jsonb(t)-'billing_policy_version')::text,'' order by (to_jsonb(t)-'billing_policy_version')::text),'')) fingerprint from public.essay_attempts t union all select 'essay_evaluations' name,md5(coalesce(string_agg((to_jsonb(t)-'billing_policy_version')::text,'' order by (to_jsonb(t)-'billing_policy_version')::text),'')) fingerprint from public.essay_evaluations t union all select 'essay_evaluation_dimensions' name,md5(coalesce(string_agg((to_jsonb(t)-'billing_policy_version')::text,'' order by (to_jsonb(t)-'billing_policy_version')::text),'')) fingerprint from public.essay_evaluation_dimensions t union all select 'essay_improvement_items' name,md5(coalesce(string_agg((to_jsonb(t)-'billing_policy_version')::text,'' order by (to_jsonb(t)-'billing_policy_version')::text),'')) fingerprint from public.essay_improvement_items t union all select 'essay_improvement_progress' name,md5(coalesce(string_agg((to_jsonb(t)-'billing_policy_version')::text,'' order by (to_jsonb(t)-'billing_policy_version')::text),'')) fingerprint from public.essay_improvement_progress t union all select 'essay_evaluation_evidence' name,md5(coalesce(string_agg((to_jsonb(t)-'billing_policy_version')::text,'' order by (to_jsonb(t)-'billing_policy_version')::text),'')) fingerprint from public.essay_evaluation_evidence t union all select 'essay_generated_rewrites' name,md5(coalesce(string_agg((to_jsonb(t)-'billing_policy_version')::text,'' order by (to_jsonb(t)-'billing_policy_version')::text),'')) fingerprint from public.essay_generated_rewrites t union all select 'essay_learning_events' name,md5(coalesce(string_agg((to_jsonb(t)-'billing_policy_version')::text,'' order by (to_jsonb(t)-'billing_policy_version')::text),'')) fingerprint from public.essay_learning_events t union all select 'essay_ai_processing_runs' name,md5(coalesce(string_agg((to_jsonb(t)-'billing_policy_version')::text,'' order by (to_jsonb(t)-'billing_policy_version')::text),'')) fingerprint from public.essay_ai_processing_runs t union all select 'credit_accounts' name,md5(coalesce(string_agg((to_jsonb(t)-'billing_policy_version')::text,'' order by (to_jsonb(t)-'billing_policy_version')::text),'')) fingerprint from public.credit_accounts t union all select 'credit_grants' name,md5(coalesce(string_agg((to_jsonb(t)-'billing_policy_version')::text,'' order by (to_jsonb(t)-'billing_policy_version')::text),'')) fingerprint from public.credit_grants t union all select 'essay_billing_decisions' name,md5(coalesce(string_agg((to_jsonb(t)-'billing_policy_version')::text,'' order by (to_jsonb(t)-'billing_policy_version')::text),'')) fingerprint from public.essay_billing_decisions t union all select 'credit_transactions' name,md5(coalesce(string_agg((to_jsonb(t)-'billing_policy_version')::text,'' order by (to_jsonb(t)-'billing_policy_version')::text),'')) fingerprint from public.credit_transactions t) f)) snapshot;
rollback;
